### 2. SERVER ENDPOINT: `/api/playground/run`

Located at lines 988-1038 in `/Users/yashbaldha/Desktop/Boldteq App/claude-hub/src/server.js`

```javascript
app.post('/api/playground/run', (req, res) => {
  const { agentName, prompt: userPrompt, customInstructions } = req.body;
  if (!userPrompt) return res.status(400).json({ error: 'Prompt is required' });

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);

  (async () => {
    try {
      // Load agent instructions
      let instructions = '';
      if (agentName) {
        const agentContentMap = {};
        const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
        if (fs.existsSync(globalAgentsDir)) {
          for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
            const content = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
            const nameMatch = content.match(/^name:\s*(.+)$/m);
            const key = nameMatch ? nameMatch[1].trim() : file.replace('.md', '');
            agentContentMap[key] = content;
            agentContentMap[file.replace('.md', '')] = content;
          }
        }
        instructions = agentContentMap[agentName] || '';
      }

      // Use custom instructions override if provided
      if (customInstructions) {
        instructions = customInstructions;
      }

      let fullPrompt = '';
      if (instructions) {
        fullPrompt = `${instructions}\n\n---\n\n## Task:\n${userPrompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
      } else {
        fullPrompt = userPrompt;
      }

      send({ type: 'start', agent: agentName || 'custom' });
      const output = await runClaudeSync(fullPrompt);
      send({ type: 'done', output });
      send({ type: 'complete', output });
    } catch (err) {
      send({ type: 'error', error: err.message });
    }
    res.end();
  })();
});
```

**Key Details:**
- Accepts: `agentName`, `prompt`, `customInstructions` (optional override)
- Loads agent from `~/.claude/agents/` directory
- Builds full prompt with agent instructions + task + instruction to not output meta-commentary
- Uses `runClaudeSync()` which spawns Claude CLI with 120s timeout
- SSE events: `start`, `done`, `complete`, `error`
- Sends output in `done` and `complete` events

